static const z_t5779_t _zag1580 = { { .data = "chan_drop_sender", .size = 16 }, { .length = 1, .data = _zag1578 }, { .length = 5, .data = _zag1579 }, { .data = "/* a Sender ends: the last one wakes a receiver waiting for a value that can\n   no longer come */\nstatic void z_chan_drop_sender(z_chan* b) {\n    z_mutex_lock(&b->m);\n    b->senders--;\n    bool last = b->senders == 0;\n    bool gone = last && !b->receiverAlive;\n    if (last) z_cond_broadcast(&b->notEmpty);\n    z_mutex_unlock(&b->m);\n    if (gone) z_chan_free(b);\n}", .size = 365 } };
